"use client"

// Top and bottom viewport scrims, scroll-linked (see scrims.css for why they are never
// transitioned). Pure CSS where animation-timeline: scroll() exists; a passive scroll
// listener measures opacity elsewhere. Place it inside the element that scrolls
// (the document, or a scrolling inset): the timeline is scroll(nearest).

import * as React from "react"
import { cn } from "@/lib/utils"
import "./scrims.css"

export interface ScrimsProps {
  /** A sticky blurred header IS a top scrim; such a page opts out of this one. */
  top?: boolean
  bottom?: boolean
  /** Absolute overlays stay inside a positioned container, such as a phone. */
  position?: "fixed" | "absolute"
  /** Static scrims protect floating chrome even at the end of a conversation. */
  mode?: "scroll" | "static"
  className?: string
  /** Explicit scroll owner, independent of where the overlays are painted. */
  scrollRef?: React.RefObject<HTMLElement | null>
}

export function Scrims({
  top = true,
  bottom = true,
  position = "fixed",
  mode = "scroll",
  className,
  scrollRef,
}: ScrimsProps) {
  const topRef = React.useRef<HTMLDivElement>(null)
  const bottomRef = React.useRef<HTMLDivElement>(null)

  React.useEffect(() => {
    if (mode === "static" || (!top && !bottom)) return
    if (!scrollRef && CSS.supports("animation-timeline: scroll()")) return
    let ancestor = (topRef.current ?? bottomRef.current)?.parentElement
    while (
      ancestor &&
      !/(auto|scroll|hidden)/.test(getComputedStyle(ancestor).overflowY)
    )
      ancestor = ancestor.parentElement
    const target =
      scrollRef?.current ??
      ancestor ??
      (document.scrollingElement as HTMLElement)
    const measure = () => {
      const y = target.scrollTop
      const remaining = target.scrollHeight - target.clientHeight - y
      if (topRef.current)
        topRef.current.style.opacity = String(Math.max(0, Math.min(1, y / 160)))
      if (bottomRef.current)
        bottomRef.current.style.opacity = String(
          Math.max(0, Math.min(1, remaining / 140)),
        )
    }
    const source = target === document.scrollingElement ? window : target
    source.addEventListener("scroll", measure, { passive: true })
    window.addEventListener("resize", measure)
    const resize = new ResizeObserver(measure)
    const observe = () => {
      resize.disconnect()
      resize.observe(target)
      for (const child of target.children) resize.observe(child)
      measure()
    }
    const mutation = new MutationObserver(observe)
    mutation.observe(target, {
      childList: true,
      subtree: true,
      characterData: true,
    })
    observe()
    measure()
    return () => {
      source.removeEventListener("scroll", measure)
      window.removeEventListener("resize", measure)
      resize.disconnect()
      mutation.disconnect()
    }
  }, [mode, top, bottom, scrollRef])

  return (
    <>
      {bottom && (
        <div
          ref={bottomRef}
          data-slot="scrim-bottom"
          style={{ margin: 0, animation: scrollRef ? "none" : undefined }}
          aria-hidden
          data-position={position}
          data-mode={mode}
          className={cn("ag-scrim", className)}
          data-edge="bottom"
        />
      )}
      {top && (
        <div
          ref={topRef}
          data-slot="scrim-top"
          style={{ margin: 0, animation: scrollRef ? "none" : undefined }}
          aria-hidden
          data-position={position}
          data-mode={mode}
          className={cn("ag-scrim", className)}
          data-edge="top"
        />
      )}
    </>
  )
}

@layer theme, base, components, utilities;

@layer components {
  /* scrims: viewport fogs that keep the section below from competing with the one on
   screen. Masked backdrop-blur + gradient, no layout, no pointer. Their opacity is
   scroll-LINKED, never transitioned: the top one fades in over the first 160px of
   scroll, the bottom one fades out over the last 140px, and on a page that cannot
   scroll the timeline is inactive so both rest at 0. A transitioned scrim (opacity
   0→1 over 500ms) crossfades WHILE a smooth anchor scroll is flying; that was the
   "weird effects" complaint. Linked to scroll it simply is where the scroll is. */

  .ag-scrim {
    position: fixed;
    right: 0;
    left: 0;
    z-index: 20;
    /* A margin on a fixed box is part of where it lands: `top + margin + height +
     margin + bottom` has to equal the viewport, so a parent's `space-y-16` (which in
     Tailwind v4 is a margin-block-end on every child but the last) pushed the bottom
     fog 64px UP off the edge, with the page showing underneath it. The component
     resets margin inline so parent spacing utilities cannot override it across
     cascade layers. */
    pointer-events: none;
    opacity: 0;
    -webkit-backdrop-filter: blur(var(--scrim-blur, 4px));
    backdrop-filter: blur(var(--scrim-blur, 4px));
  }
  .ag-scrim[data-edge="top"] {
    top: 0;
    height: var(--scrim-top-height, 5rem);
    background: linear-gradient(
      to bottom,
      color-mix(
          in oklab,
          var(--scrim-color, var(--background)) var(--scrim-strength, 90%),
          transparent
        )
        var(--scrim-start-stop, 0%),
      color-mix(
          in oklab,
          var(--scrim-color, var(--background)) var(--scrim-mid-strength, 35%),
          transparent
        )
        var(--scrim-mid-stop, 50%),
      transparent
    );
    mask-image: linear-gradient(
      to bottom,
      black var(--scrim-solid-stop, 25%),
      transparent
    );
  }
  .ag-scrim[data-edge="bottom"] {
    bottom: 0;
    height: var(--scrim-bottom-height, 7rem);
    background: linear-gradient(
      to top,
      color-mix(
        in oklab,
        var(--scrim-color, var(--background)) var(--scrim-strength, 90%),
        transparent
      ),
      color-mix(
          in oklab,
          var(--scrim-color, var(--background)) var(--scrim-mid-strength, 35%),
          transparent
        )
        var(--scrim-mid-stop, 50%),
      transparent
    );
    mask-image: linear-gradient(
      to top,
      black var(--scrim-solid-stop, 25%),
      transparent
    );
  }

  .ag-scrim[data-position="absolute"] {
    position: absolute;
  }
  .ag-scrim[data-mode="static"] {
    opacity: 1;
  }

  @keyframes ag-scrim-top {
    from {
      opacity: 0;
    }
    to {
      opacity: 1;
    }
  }
  @keyframes ag-scrim-bottom {
    from {
      opacity: 1;
    }
    to {
      opacity: 0;
    }
  }

  @supports (animation-timeline: scroll()) {
    .ag-scrim[data-mode="scroll"][data-edge="top"] {
      animation: ag-scrim-top linear both;
      animation-timeline: scroll(nearest);
      animation-range: 0 160px;
    }
    .ag-scrim[data-mode="scroll"][data-edge="bottom"] {
      animation: ag-scrim-bottom linear both;
      animation-timeline: scroll(nearest);
      animation-range: calc(100% - 140px) 100%;
    }
  }
}
